 35	/* at most this many arguments are handed over to a new process */
 36	#define MAX_EXEC_ARGC 16
 37	
 38	/*
 39	 * A brand new address space costs a few frames right away (the ELF image, the
 40	 * first stack page and the kernel stack).  Refuse to exec instead of running
 41	 * into an allocation that cannot be satisfied even by swapping.
 42	 */
 43	#define EXEC_MIN_FREE_PAGES 16
 44	
 45	static void reclaim_pcb(pcb_t *task);
 46	
 47	/*
 48	 * Only modify PCB, current_running, process_id and ready_queue
 49	 * DO NOT STORE OR RESTORE
 50	 * trick: modify $tp in ret_from_exception to ensure
 51	 * disable_preempt() and enable_preempt() modify the same PCB
 52	 */
 53	void scheduler(void)
 54	{
 55	    pcb_t *prev = current_running[cpu_id];
 56	    pcb_t *next;
 57	    pcb_t *dying = NULL;
 58	    list_node_t *next_node;
 59	
 60	    if (prev != &kernel_pcb[cpu_id]) {
 61	        if (prev->status == TASK_RUNNING) {
 62	            /* still runnable: back to the tail of the ready queue */
 63	            prev->status = TASK_READY;
 64	            prev->ready_tick = get_ticks();
 65	            list_add_tail(&prev->list, &ready_queue);
 66	        } else if (prev->status == TASK_KILLED) {
 67	            /* it died on this core; its address space can only be torn down
 68	             * once `satp` no longer points at it, so remember it for now */
 69	            list_del(&prev->list);
 70	            dying = prev;
 71	        }
 72	    }
 73	
 74	    next_node = max_priority_node();
 75	    if (next_node == NULL) {
 76	        /* nothing this hart may run, go back to its idle task */
 77	        next = &kernel_pcb[cpu_id];
 78	    } else {
 79	        list_del(next_node);
 80	        next = list_entry(next_node, pcb_t, list);
 81	    }
 82	
 83	    next->status = TASK_RUNNING;
 84	    next->cpu_id = cpu_id;
 85	    current_running[cpu_id] = next;
 86	    /* ret_from_exception restores the context of `current_cpu_running` */
 87	    current_cpu_running = next;
 88	
 89	    /* every task owns its own cursor position */
 90	    screen_cursor_x[cpu_id] = next->cursor_x;
 91	    screen_cursor_y[cpu_id] = next->cursor_y;
 92	
 93	    /* install the address space of the new task; the kernel window is part
 94	     * of every page table, so the code below keeps running just fine */
 95	    set_satp(SATP_MODE_SV39, 0, ((uintptr_t)next->pgdir) >> NORMAL_PAGE_SHIFT);
 96	    local_flush_tlb_all();
 97	
 98	    if (dying != NULL) {
 99	        free_process_user_page(dying->pgdir);
100	        dying->pgdir = (PTE*)PGDIR_PA;
101	        reclaim_pcb(dying);
102	    }
103	}
