563	int do_taskset(pid_t pid, unsigned long mask)
564	{
565	    // search the pcb
566	    pcb_t *set_pcb = NULL;
567	    for(int i = 0; i < NUM_MAX_TASK; i++){
568	        if(pcb[i].pid == pid){
569	            set_pcb = &pcb[i];
570	            break;
571	        }
572	    }
573	    if(set_pcb == NULL){
574	        return 0;
575	    }
576	
577	    set_pcb->mask = mask;
578	    return 1;
579	}
