/* used to save register infomation */
typedef struct regs_context
{
    /* Saved main processor registers.*/
    reg_t regs[32];

    /* Saved special registers. */
    reg_t sstatus;
    reg_t sepc;
    reg_t stval;
    reg_t scause;
    reg_t sscratch;
} regs_context_t;

typedef enum {
    TASK_BLOCKED,
    TASK_RUNNING,
    TASK_READY,
    TASK_ZOMBIE,
    TASK_EXITED,
    TASK_KILLED,
} task_status_t;

typedef enum {
    ENTER_ZOMBIE_ON_EXIT,
    AUTO_CLEANUP_ON_EXIT,
} spawn_mode_t;

typedef enum {
    KERNEL_PROCESS,
    KERNEL_THREAD,
    USER_PROCESS,
    USER_THREAD,
} task_type_t;

/* Process Control Block */
typedef struct pcb
{
    /* register context */
    // this must be this order!! The order is defined in regs.h
    reg_t kernel_sp;
    reg_t user_sp;

    // count the number of disable_preempt
    // enable_preempt enables CSR_SIE only when preempt_count == 0
    reg_t preempt_count;

    ptr_t kernel_stack_base;
    ptr_t user_stack_base;

    /* previous, next pointer and wait queue*/
    list_node_t list;
    list_head wait_list;

    /* acquired binsem lock */
    int binsem_id[100];
    int binsem_num;

    /* sleep timer */
    timer_t timer;

    /* process id */
    pid_t pid;

    /* kernel/user thread/process */
    task_type_t type;

    /* BLOCK | READY | RUNNING | ZOMBIE */
    task_status_t status;
    spawn_mode_t mode;

    /* priority and wait time */
    uint8_t priority;
    uint64_t ready_tick;

    /* hart mask */
    unsigned long mask;
    unsigned long cpu_id;

    /* pgdir */
    PTE *pgdir;

    /* cursor position */
    int cursor_x;
    int cursor_y;
} pcb_t;

/* task information, used to init PCB */
typedef struct task_info
{
    ptr_t entry_point;
    task_type_t type;
    uint8_t priority;
} task_info_t;

/* ready queue to run */
extern list_head ready_queue;
extern list_head sleep_queue;

